import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import classNames from 'classnames'
import {memo} from 'react'

import CommentPopup from '../../CommentPopup/CommentPopup'
import {useSequenceLoaderReadyHandler} from '../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../SequenceLoader/SequenceLoader.types'

import type {EntityType} from './StatusBadge.consts'
import {useStatusIcon, useStatusInfo} from './StatusBadge.hooks'

import styles from './StatusBadge.module.css'

import Badge from 'src/components/common/Badge/Badge'
import Icon from 'src/components/common/Icon/Icon'
import type {BuildTypeId, CommentInfo} from 'src/types'
import {BuildStatusType} from 'src/types'

const DIRECTIONS = [Directions.BOTTOM_RIGHT, Directions.BOTTOM_LEFT]

type Props = {
  className?: string
  buildTypeId?: BuildTypeId
  status: BuildStatusType
  statusChangeComment?: CommentInfo | null
  canceledInfo?: CommentInfo | null
  waitReason?: string
  failedToStart?: boolean
  isRunning?: boolean
  type?: EntityType
}

function StatusBadge({
  className,
  buildTypeId,
  status,
  statusChangeComment,
  canceledInfo,
  waitReason,
  failedToStart,
  isRunning,
  type,
}: Props & SeqProps) {
  const isFailed = status === BuildStatusType.FAILURE
  useSequenceLoaderReadyHandler(true)

  const {statusText, tooltipText} = useStatusInfo(
    status,
    statusChangeComment,
    canceledInfo,
    waitReason,
    failedToStart,
    isRunning,
    type,
  )

  const icon = useStatusIcon(status, isRunning, failedToStart)

  const anchor = (
    <div
      className={classNames(
        styles.status,
        isRunning ? (isFailed ? styles.failure : styles.running) : null,
        !isRunning && styles[status],
      )}
    >
      <Icon className={styles.icon} name={icon} />
      {statusText}
    </div>
  )

  return (
    <Badge className={classNames(styles.container, className)} label={'Status'}>
      <CommentPopup
        className={styles.tooltip}
        anchor={anchor}
        text={tooltipText}
        buildTypeId={buildTypeId}
        directions={DIRECTIONS}
        top={4}
        timestamp={!canceledInfo ? statusChangeComment?.timestamp : null}
      />
    </Badge>
  )
}

export default memo(StatusBadge)
