import {memo, useCallback, useState} from 'react'

import type {
  Optimization,
  PossibleOptimization,
  RunDuration,
} from '../../../pages/PipelinesPages/services/pipelinesApi.types'
import {useSequenceLoaderReadyHandler} from '../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../SequenceLoader/SequenceLoader.types'

import BaseTimeBadge from './BaseTimeBadge/BaseTimeBadge'
import OptimizationsChart from './OptimizationsPopup/OptimizationsChart/OptimizationsChart'
import OptimizationsPopup from './OptimizationsPopup/OptimizationsPopup'

type BaseProps = {
  duration?: number | null
  queueDuration?: number | null
  estimatedDuration?: number | null
  optimizedDuration?: number | null
  date?: string
  withAppliedOptimizations?: boolean
  isRunning?: boolean
  isQueued?: boolean
  isLoading?: boolean
  queuePosition?: number
  title?: string
  clickable?: boolean
  className?: string
  buildId?: number
  dataTestId?: string
}
type PopupProps = {
  optimizations?: Optimization[]
  possibleOptimizations?: PossibleOptimization[]
  popupClassName?: string
  popupTitle?: string | null
  hasNoRuns?: boolean
  runs?: RunDuration[]
}

type Props = BaseProps & PopupProps & SeqProps
function TimeBadge({
  duration,
  estimatedDuration,
  optimizedDuration,
  isQueued,
  queuePosition,
  title,
  optimizations,
  possibleOptimizations,
  date,
  hasNoRuns,
  runs,
  popupTitle,
  popupClassName,
  clickable = true,
  ...props
}: Props) {
  const [open, setOpen] = useState(false)

  useSequenceLoaderReadyHandler(true)

  const togglePopup = useCallback(() => {
    setOpen(prevState => !prevState)
  }, [])

  return (
    <OptimizationsPopup
      anchor={
        <BaseTimeBadge
          duration={duration}
          estimatedDuration={estimatedDuration}
          optimizedDuration={optimizedDuration}
          date={date}
          isQueued={isQueued}
          queuePosition={queuePosition}
          open={open}
          clickable={clickable}
          title={title}
          {...props}
        />
      }
      className={popupClassName}
      title={popupTitle ?? title}
      disabled={!clickable}
      hasNoRuns={hasNoRuns}
      duration={duration}
      estimatedDuration={estimatedDuration}
      optimizedDuration={optimizedDuration}
      optimizations={optimizations}
      possibleOptimizations={possibleOptimizations}
      additionalBlock={runs?.length ? <OptimizationsChart runs={runs} /> : null}
      onClick={togglePopup}
    />
  )
}

export default memo(TimeBadge)
