import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import type {CSSProperties} from 'react'
import {memo, useRef} from 'react'
import type {TransitionStatus} from 'react-transition-group'
import {Transition} from 'react-transition-group'

import BuildQueueInfo from '../../../BuildQueueInfo/BuildQueueInfo.container'
import Icon from '../../../Icon/Icon'
import {HUNDRED_PERCENT} from '../TimeBadge.constants'
import {useOptimizedPercent} from '../TimeBadge.hooks'
import TimeBar, {BarType} from '../TimeBar/TimeBar'

import styles from './BaseTimeBadge.module.css'

import Badge from 'src/components/common/Badge/Badge'
import SwitcherLabel from 'src/components/common/SwitcherLabel/SwitcherLabel'
import {formatDuration} from 'src/utils/dateTimeUtils'

const TRANSITION_DURATION = 300
const TRANSITIONS: Partial<Record<TransitionStatus, CSSProperties>> = {
  entering: {transform: 'translateX(100%)', opacity: 0},
  entered: {
    transition: 'transform 300ms cubic-bezier(0.36, 1.33, 0.64, 1)',
    transform: 'translateX(0%)',
    opacity: 1,
  },
}

type Props = {
  duration?: number | null
  queueDuration?: number | null
  estimatedDuration?: number | null
  optimizedDuration?: number | null
  withAppliedOptimizations?: boolean
  date?: string
  queuePosition?: number
  isRunning?: boolean
  isQueued?: boolean
  isLoading?: boolean
  title?: string
  clickable?: boolean
  open?: boolean
  className?: string
  buildId?: number
  dataTestId?: string
}
function BaseTimeBadge({
  duration,
  queueDuration,
  estimatedDuration,
  optimizedDuration,
  withAppliedOptimizations,
  date,
  queuePosition,
  isRunning,
  isQueued,
  isLoading,
  title = 'Run duration',
  clickable,
  open,
  className,
  buildId,
  dataTestId,
}: Props) {
  const percentRef = useRef(null)
  const optimizedPercent = useOptimizedPercent(duration, Number(optimizedDuration))

  return (
    <Badge
      dataTestId={dataTestId}
      clickable={clickable && !isQueued && !isLoading}
      className={classNames(styles.badge, className)}
    >
      {isLoading ? (
        <>
          <div className={styles.label}>{title}</div>
          <div className={styles.skeleton} />
        </>
      ) : isQueued ? (
        <div className={styles.inQueue}>
          <div className={styles.label}>{'In queue'}</div>
          <TimeBar
            containerClassName={styles.timeBarContainer}
            inProgress={isQueued}
            type={BarType.QUEUE}
          />
          <div>
            {queuePosition && `#${queuePosition} in the build queue - `}
            {!buildId && formatDuration(queueDuration)}
            {buildId && (
              <BuildQueueInfo className={styles.buildQueueInfo} buildId={buildId!} withoutTitle />
            )}
          </div>
        </div>
      ) : (
        <div className={styles.running}>
          {!!queueDuration && (
            <div className={styles.queueContainer}>
              <div className={styles.label}>{'In queue'}</div>
              <TimeBar type={BarType.QUEUE} containerClassName={styles.timeBarContainer} />
              {buildId ? (
                <BuildQueueInfo
                  buildId={buildId!}
                  withoutTitle
                  className={styles.buildQueueInfo}
                  anchorClassName={styles.queueAnchor}
                />
              ) : (
                formatDuration(queueDuration)
              )}
            </div>
          )}
          <div className={styles.runningContainer}>
            <div className={styles.labels}>
              <div className={classNames(styles.label, styles.left)}>{title}</div>
              {clickable ? (
                <div className={styles.row}>
                  <div className={classNames(styles.label, styles.right)}>{'Optimization'}</div>
                  <SwitcherLabel on={withAppliedOptimizations} />
                </div>
              ) : null}
            </div>
            <TimeBar
              containerClassName={styles.timeBarContainer}
              inProgress={isRunning}
              value={optimizedPercent ? HUNDRED_PERCENT - optimizedPercent : null}
              type={
                duration === 0
                  ? BarType.QUEUE
                  : optimizedPercent
                    ? BarType.OPTIMIZED
                    : BarType.DEFAULT
              }
            />
            <div className={styles.labels}>
              <div className={styles.row}>
                {duration === 0 ? '0s' : formatDuration(duration)}
                {isRunning && !!estimatedDuration && (
                  <div className={styles.highlighted}>{`${formatDuration(
                    Number(estimatedDuration),
                  )} left`}</div>
                )}
                {!isRunning && date && ` (${date})`}
              </div>

              {optimizedPercent ? (
                <Transition in nodeRef={percentRef} unmountOnExit timeout={TRANSITION_DURATION}>
                  {state => (
                    <div
                      className={styles.right}
                      style={TRANSITIONS[process.env.NODE_ENV === 'test' ? 'entered' : state]}
                    >
                      <Button
                        data-test-time-badge-anchor
                        className={styles.optimizationsButton}
                        inline
                        title={open ? 'Close' : 'Open'}
                      >
                        <div className={styles.optimization}>
                          <div>{`-${optimizedPercent}%`}</div>
                          <Icon
                            className={styles.arrow}
                            name={open ? 'chevron-up' : 'chevron-down'}
                          />
                        </div>
                      </Button>
                    </div>
                  )}
                </Transition>
              ) : null}
            </div>
          </div>
        </div>
      )}
    </Badge>
  )
}

export default memo(BaseTimeBadge)
