import Dropdown, {Anchor} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import classNames from 'classnames'
import {Fragment, useCallback, useState} from 'react'

import EntityLink from '../../../../containers/EntityLink'
import {useAppSelector} from '../../../../hooks/react-redux'
import {
  getBuild,
  getPipelineIdFromBuildId,
  getPipelineRunIdFromBuildId,
} from '../../../../selectors'
import {BuildPageTabNamesEnum, stringifyId} from '../../../../types'
import {formatDuration} from '../../../../utils/dateTimeUtils'
import Popup from '../../Popup/Popup.lazy'
import RouterLink from '../../RouterLink/RouterLink'
import {WaitReasons} from '../BuildQueueInfo.consts'
import styles from '../BuildQueueInfo.module.css'
import type {WaitReason} from '../BuildQueueInfo.types'

import {useWaitReasons} from './WaitReasonsList.hooks'
import type {Props} from './WaitReasonsList.types'

const INTERVAL = 5000

function WaitReasonsList({
  buildId,
  groupOwnReasons,
  timeInQueue,
  queued,
  currentWaitReason,
  withIcons,
  dependenciesRange,
  inline,
  title,
  anchorClassName,
}: Props) {
  const [isOpen, setIsOpen] = useState(false)
  const onShow = useCallback(() => setIsOpen(true), [])
  const onHide = useCallback(() => setIsOpen(false), [])
  const buildTypeId = useAppSelector(state => getBuild(state, buildId)?.buildType)
  const pipelineId = useAppSelector(state => getPipelineIdFromBuildId(state, buildId))
  const runId = useAppSelector(state => getPipelineRunIdFromBuildId(state, buildId))
  const waitReasons = useWaitReasons(buildId, (isOpen || inline) && queued ? INTERVAL : null)
  const other = waitReasons.reduce(
    (acc, {durationInSeconds}) => acc - durationInSeconds,
    timeInQueue,
  )
  const allReasons =
    other >= 1 && !queued
      ? [
          ...waitReasons,
          {
            reason: 'Other',
            durationInSeconds: other,
          },
        ]
      : waitReasons
  const formattedDurationLessPrefix = 'less than'
  const formatReason = ({reason, durationInSeconds}: WaitReason, index: number) => {
    const isWaitForDependencies = reason === WaitReasons.DEPENDENCY_NOT_READY
    const isCurrentReason = currentWaitReason === reason
    const duration = isCurrentReason ? durationInSeconds + other : durationInSeconds
    const formattedDuration = formatDuration(duration, {
      lessPrefix: formattedDurationLessPrefix,
    })
    const isLessThanOneSecond = formattedDuration.startsWith(formattedDurationLessPrefix)
    const reasonText = <div key="reasonText">{reason}</div>
    const reasonTime = (
      <div key="reasonTime" className={styles.reasonTime}>
        {withIcons && <span className={styles.iconsOffset} />}
        {!isWaitForDependencies ? (
          <span
            className={classNames({
              [styles.lessThanOneSecond]: isLessThanOneSecond,
            })}
          >
            {formattedDuration}
          </span>
        ) : dependenciesRange != null ? (
          <RouterLink params={params => ({...params, range: dependenciesRange})}>
            {formattedDuration}
          </RouterLink>
        ) : (
          <EntityLink
            buildId={buildId}
            buildTypeId={buildTypeId}
            pipelineId={pipelineId}
            runId={runId}
            params={{
              buildTab: stringifyId(BuildPageTabNamesEnum.DEPENDENCIES),
              mode: 'timeline',
            }}
          >
            {formattedDuration}
          </EntityLink>
        )}
      </div>
    )
    const key = `reason-${index}-${reason}-${durationInSeconds}`

    return (
      <Fragment key={key}>{inline ? [reasonTime, reasonText] : [reasonText, reasonTime]}</Fragment>
    )
  }
  const dependencyReason = allReasons.find(
    ({reason}) => reason === WaitReasons.DEPENDENCY_NOT_READY,
  )
  const reasons =
    groupOwnReasons && dependencyReason != null ? (
      <>
        {formatReason(dependencyReason, 0)}
        <div className={styles.reasonTime}>
          {formatDuration(timeInQueue - dependencyReason.durationInSeconds)}
        </div>
        <div>
          {withIcons && (
            <span className={styles.iconsOffset}>
              <span className={styles.ownQueueTimeIcon} />
            </span>
          )}
          {'Own queue time'}
        </div>
        {allReasons
          .filter(({reason}) => reason !== WaitReasons.DEPENDENCY_NOT_READY)
          .map(formatReason)}
      </>
    ) : (
      allReasons.map(formatReason)
    )

  if (inline) {
    return waitReasons.length > 0 && reasons
  }

  return waitReasons.length > 0 ? (
    <Dropdown
      className={styles.dropdown}
      anchor={<Anchor className={classNames(styles.anchor, anchorClassName)}>{title}</Anchor>}
      onShow={onShow}
      onHide={onHide}
    >
      <Popup className={styles.popup}>
        <div className={styles.reason}>{reasons}</div>
      </Popup>
    </Dropdown>
  ) : (
    title
  )
}

export default WaitReasonsList
