import classNames from 'classnames'
import {useMemo} from 'react'

import {HUNDRED_PERCENT} from '../TimeBadge.constants'

import styles from './TimeBar.module.css'

export enum BarType {
  QUEUE,
  DEFAULT,
  OPTIMIZED,
}

type Props = {
  value?: number | null
  inProgress?: boolean
  className?: string
  containerClassName?: string
  type?: BarType
}
function TimeBar({
  value,
  inProgress,
  className,
  containerClassName,
  type = BarType.DEFAULT,
}: Props) {
  const width = useMemo(() => {
    if (value && value < HUNDRED_PERCENT && value > 0) {
      return `${value}%`
    }
    return `${HUNDRED_PERCENT}%`
  }, [value])

  const isOptimized = type === BarType.OPTIMIZED
  const isQueued = type === BarType.QUEUE

  return (
    <div
      className={classNames(styles.container, containerClassName, {
        [styles.optimizedContainer]: isOptimized,
      })}
    >
      <div
        style={{width}}
        className={classNames(styles.bar, className, {
          [styles.inProgress]: inProgress,
          [styles.withSeparator]: isOptimized,
          [styles.queue]: isQueued,
          [styles.default]: !isQueued,
        })}
      />
      <div
        style={{left: width, opacity: isOptimized ? 1 : 0}}
        className={classNames(styles.separator, className)}
      />
    </div>
  )
}
export default TimeBar
