import Loader from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {differenceInSeconds, parseISO} from 'date-fns'
import {Suspense} from 'react'

import useTimeSelector from '../../../hooks/useTimeSelector'
import {formatDuration} from '../../../utils/dateTimeUtils'

import type {Props} from './BuildQueueInfo.types'
import WaitReasonsList from './WaitReasonsList/WaitReasonsList'

import styles from './BuildQueueInfo.module.css'

function BuildQueueInfo({
  className,
  buildId,
  inline,
  queuedDate,
  startDate,
  currentWaitReason,
  aside,
  queued,
  titleClassName,
  reasonsClassName,
  dependenciesRange,
  withoutTitle,
  groupOwnReasons,
  withIcons,
  anchorClassName,
}: Props) {
  const startDateObj = startDate != null ? parseISO(startDate) : null
  const startOrNow = useTimeSelector(now => Number(startDateObj ?? now))

  if (queuedDate == null) {
    return null
  }

  const timeInQueue = differenceInSeconds(startOrNow, parseISO(queuedDate))
  const titleClasses = classNames(titleClassName, styles.title)
  const titleTime = (
    <span key="titleKey" className={classNames(titleClasses, {[styles.reasonTime]: inline})}>
      {formatDuration(timeInQueue)}
    </span>
  )
  const titleText = (
    <span key="titleText" className={titleClasses} data-test-queue-info="true">
      {withIcons && (
        <span className={styles.iconsOffset}>
          <SvgIcon icon="hourglass" className={styles.queuedIcon} />
        </span>
      )}
      {!withoutTitle && 'Queue time '}
      {inline && aside}
    </span>
  )
  const title = inline ? [titleTime, titleText] : [titleText, titleTime]
  const reasonsList = (
    <WaitReasonsList
      buildId={buildId}
      groupOwnReasons={groupOwnReasons}
      timeInQueue={timeInQueue}
      queued={queued}
      currentWaitReason={currentWaitReason}
      withIcons={withIcons}
      dependenciesRange={dependenciesRange}
      inline={inline}
      title={title}
      anchorClassName={anchorClassName}
    />
  )

  if (!inline) {
    return (
      <div className={classNames(className, styles.wrapper, styles.reason)}>
        <Suspense fallback={title}>{reasonsList}</Suspense>
      </div>
    )
  }

  return (
    <div
      className={classNames(
        className,
        reasonsClassName,
        styles.wrapper,
        styles.reason,
        styles.inlineReasons,
      )}
    >
      {title}
      <Suspense fallback={<Loader>{'Loading reasons...'}</Loader>}>{reasonsList}</Suspense>
    </div>
  )
}

export default BuildQueueInfo
