import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {objectEntries} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import type {ReactElement, ReactNode} from 'react'
import {memo} from 'react'

import {formatDuration, formatDurationToObject} from '../../../../../utils/dateTimeUtils'
import {formatSize} from '../../../../../utils/sizeUtils'
import type {
  Optimization,
  PossibleOptimization,
} from '../../../../pages/PipelinesPages/services/pipelinesApi.types'
import {
  Optimizations,
  OptimizationType,
} from '../../../../pages/PipelinesPages/services/pipelinesApi.types'
import SwitcherLabel from '../../../SwitcherLabel/SwitcherLabel'
import {HUNDRED_PERCENT} from '../TimeBadge.constants'
import {useOptimizedPercent} from '../TimeBadge.hooks'
import TimeBar from '../TimeBar/TimeBar'

import {OPTIMIZATION_OPTIONS} from './OptimizationsPopup.consts'
import PossibleOptimizations from './PossibleOptimizations/PossibleOptimizations'

import styles from './OptimizationsPopup.module.css'

type Props = {
  anchor: ReactElement
  duration?: number | null
  estimatedDuration?: number | null
  optimizedDuration?: number | null
  optimizations?: Optimization[]
  possibleOptimizations?: PossibleOptimization[]
  disabled?: boolean
  title?: string
  additionalBlock?: ReactNode
  hasNoRuns?: boolean
  className?: string
  onClick?: () => void
}
function OptimizationsPopup({
  anchor,
  duration,
  estimatedDuration,
  optimizedDuration,
  optimizations,
  possibleOptimizations,
  disabled,
  title = 'Run duration',
  additionalBlock,
  hasNoRuns,
  className,
  onClick,
}: Props) {
  const optimizedPercent = useOptimizedPercent(duration, Number(optimizedDuration))
  const total = formatDurationToObject(duration)
  const optimized = formatDurationToObject(optimizedDuration)
  const getFormattedValue = (value: number, type: OptimizationType): string | null => {
    if (!value) {
      return null
    }

    switch (type) {
      case OptimizationType.DURATION:
        return formatDuration(Number(value), {hideZero: true})
      case OptimizationType.SIZE:
        return formatSize(Number(value))
      default:
        return null
    }
  }

  return (
    <Dropdown
      anchor={anchor}
      className={classNames(styles.dropdown, className)}
      onClickCapture={onClick}
      disabled={disabled}
    >
      <Popup
        className={styles.popup}
        directions={[Directions.BOTTOM_LEFT, Directions.BOTTOM_RIGHT]}
        onOutsideClick={onClick}
      >
        <div className={styles.content}>
          <div>
            <div className={styles.secondaryLabel}>{title}</div>
            <div className={styles.time}>
              <div className={styles.duration}>
                {objectEntries(total).map(([key, value]) =>
                  value ? (
                    <div key={key}>
                      <span className={styles.durationValue}>{value}</span>
                      <span>{key}</span>
                    </div>
                  ) : null,
                )}
              </div>
              {estimatedDuration ? (
                <div className={styles.highlighted}>{`${formatDuration(
                  estimatedDuration,
                )} left`}</div>
              ) : null}
            </div>
          </div>
          {optimizedPercent ? (
            <div>
              <div className={styles.secondaryLabel}>{'Time saved'}</div>
              <div className={styles.time}>
                <div className={styles.duration}>
                  {objectEntries(optimized).map(([key, value]) =>
                    value ? (
                      <div key={key}>
                        <span className={styles.durationValue}>{value}</span>
                        <span>{key}</span>
                      </div>
                    ) : null,
                  )}
                </div>
                <div
                  className={styles.highlighted}
                >{`${optimizedPercent}% of the original duration`}</div>
              </div>
            </div>
          ) : null}
        </div>
        {!!optimizations?.length || !!possibleOptimizations?.length || additionalBlock ? (
          <div className={styles.content}>
            <div className={styles.heading}>
              <div className={styles.header}>{'Smart optimization features'}</div>
              {!optimizations?.length && (
                <div className={styles.subheader}>
                  {'Use optimization features to reduce job run duration.'}
                </div>
              )}
            </div>

            {optimizations?.length
              ? optimizations?.map(({value, name, type}, index) => {
                  const percent =
                    type === OptimizationType.DURATION && optimizedDuration
                      ? Math.round((HUNDRED_PERCENT * value) / optimizedDuration)
                      : null
                  const formattedValue = getFormattedValue(value, type)

                  const showTimeBar =
                    type === OptimizationType.DURATION && name !== Optimizations.PARALLEL_TESTING

                  const optimization = OPTIMIZATION_OPTIONS[name as Optimizations]
                  return (
                    // eslint-disable-next-line react/no-array-index-key
                    <div key={index} className={styles.optimizationContainer}>
                      <div className={styles.optimization}>
                        <div className={styles.primaryLabel}>
                          <SwitcherLabel on className={styles.onLabel} />
                          <span>{optimization.name}</span>
                        </div>
                        {formattedValue && (
                          <div className={classNames(styles.primaryLabel, styles.timeLabel)}>
                            {formattedValue}
                          </div>
                        )}
                      </div>
                      {showTimeBar && (
                        <TimeBar
                          containerClassName={styles.timeBarContainer}
                          className={styles.timeBar}
                          value={percent}
                        />
                      )}
                      {hasNoRuns ? <span className={styles.hint}>{optimization.hint}</span> : null}
                    </div>
                  )
                })
              : null}
            {possibleOptimizations && (
              <PossibleOptimizations optimizations={possibleOptimizations} />
            )}
          </div>
        ) : null}
        {additionalBlock && <div className={styles.content}>{additionalBlock}</div>}
      </Popup>
    </Dropdown>
  )
}

export default memo(OptimizationsPopup)
