const KILOBYTE = 0x400
const MEGABYTE = 0x100000
const GIGABYTE = 0x40000000
const TERABYTE = 0x10000000000

export function formatSize(size: number): string {
  const sign = size >= 0 ? '' : '-'
  const sizeAbs = Math.abs(size)

  if (sizeAbs < KILOBYTE) {
    return `${sign + sizeAbs.toFixed(0)} B`
  } else if (sizeAbs < MEGABYTE) {
    return `${sign + (sizeAbs / KILOBYTE).toFixed(2)} KB`
  } else if (sizeAbs < GIGABYTE) {
    return `${sign + (sizeAbs / MEGABYTE).toFixed(2)} MB`
  } else if (sizeAbs < TERABYTE) {
    return `${sign + (sizeAbs / GIGABYTE).toFixed(2)} GB`
  }
  return `${sign + (sizeAbs / TERABYTE).toFixed(2)} TB`
}
