import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import type {ReactNode} from 'react'
import {useEffect, useMemo} from 'react'

import {useAppSelector} from '../../../../hooks/react-redux'
import {useIsAutodetectTimeZone} from '../../../../hooks/useIsAutodetectTimeZone'
import {getSingleBuildArg} from '../../../../rest/builds'
import {getBuild, getBuildAgent} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import {displayDate} from '../../../../utils/dateTimeUtils'
import {subscribeOnAgentEvents} from '../../../../utils/subscriber'
import AgentBadgeErrorState from '../../../pages/PipelinesPages/components/Badges/AgentBadge/AgentBadgeErrorState'
import AgentInfo from '../../AgentInfo/AgentInfo.container'
import Badge from '../../Badge/Badge'
import CompatibleAgents from '../../CompatibleAgents/CompatibleAgents.container'
import CopyIconButton from '../../CopyIconButton/CopyIconButton'
import Icon from '../../Icon/Icon'
import {useSequenceLoaderReadyHandler} from '../../SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../SequenceLoader/SequenceLoader.types'

import styles from './AgentBadge.module.css'

import {getBuildLocator} from 'src/rest/locators'
import {AGENT_REMOVED} from 'src/utils/subscriptionEvents'

type Props = {
  className?: string
  buildId?: number
  isShowNoCompatibleAgent?: boolean
  isShowCompatibleAgents?: boolean
  incompatibilityReasons?: ReactNode
  dataTestId?: string
} & SeqProps
function AgentBadge({
  className,
  buildId,
  isShowNoCompatibleAgent,
  isShowCompatibleAgents,
  incompatibilityReasons,
  dataTestId,
}: Props) {
  const agent = useAppSelector(state => (buildId != null ? getBuildAgent(state, buildId) : null))
  const queued = useAppSelector(state => getBuild(state, buildId)?.state === 'queued')
  const isDetached = useAppSelector(state => getBuild(state, buildId)?.detachedFromAgent)
  const finishOnAgentDate = useAppSelector(state => getBuild(state, buildId)?.finishOnAgentDate)
  const composite = useAppSelector(state => getBuild(state, buildId)?.composite)
  const isShowAgentInfo = agent != null && agent.name !== 'N/A' && buildId && !queued
  const isShowCompatibleAgentsInfo = isShowCompatibleAgents && buildId && queued && !composite
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const isRemoved = agent?.removed

  const [fetchBuild] = restApi.endpoints.getBuildNormalized.useLazyQuerySubscription()
  useEffect(
    () =>
      agent?.id
        ? subscribeOnAgentEvents(agent?.id, [AGENT_REMOVED], () =>
            fetchBuild(getSingleBuildArg(getBuildLocator(buildId))),
          )
        : undefined,
    [agent?.id, buildId, fetchBuild],
  )

  const afterName = useMemo(
    () =>
      isDetached && finishOnAgentDate ? (
        <Tooltip
          long
          delay={500}
          className={styles.detachedTooltip}
          title={`Detached from agent on ${displayDate(finishOnAgentDate, isAutodetectTimeZone, true)}`}
        >
          <Icon name={'info'} />
        </Tooltip>
      ) : (
        <CopyIconButton
          wrapperClassName={styles.copyWrapper}
          text={agent?.name}
          title={'Copy to clipboard'}
        />
      ),
    [agent?.name, finishOnAgentDate, isAutodetectTimeZone, isDetached],
  )

  const title = useMemo(() => {
    if (isRemoved) {
      return 'Removed agent'
    }
    if (isDetached) {
      return 'Detached agent'
    }
    return 'Agent'
  }, [isRemoved, isDetached])

  useSequenceLoaderReadyHandler(true)
  if (!isShowNoCompatibleAgent && !isShowAgentInfo && !isShowCompatibleAgentsInfo) {
    return null
  }

  return (
    <Badge dataTestId={dataTestId} className={className}>
      <div className={styles.wrapper}>
        <div className={styles.label}>
          <div className={styles.labelWrapper}>
            {title}
            {isShowNoCompatibleAgent && incompatibilityReasons}
          </div>
        </div>
        {isShowNoCompatibleAgent && (
          <AgentBadgeErrorState>{'No compatible agent'}</AgentBadgeErrorState>
        )}
        {isShowCompatibleAgentsInfo && (
          <CompatibleAgents className={styles.compatibleAgents} buildId={buildId} withAnchor />
        )}
        {isShowAgentInfo && (
          <AgentInfo
            className={styles.agentInfo}
            valueClassName={styles.agentInfoValue}
            linkClassName={styles.agentLink}
            buildId={buildId}
            secondary={false}
            withPool={false}
            withTooltip
            afterName={afterName}
          />
        )}
      </div>
    </Badge>
  )
}
export default AgentBadge
