import {useUserDisplayName} from '../../../../hooks/useUserDisplayName'
import type {CommentInfo} from '../../../../types'
import {BuildStatusType} from '../../../../types'

import {EntityTextMap, EntityType, StatusIconMap, StatusTextMap} from './StatusBadge.consts'

const useStatusText = (
  status: BuildStatusType,
  statusChangeComment?: CommentInfo | null,
  canceledInfo?: CommentInfo | null,
  isRunning?: boolean,
  failedToStart?: boolean,
) => {
  if (statusChangeComment && !canceledInfo) {
    return `Marked as ${StatusTextMap[status]}`
  }
  if (failedToStart) {
    return 'Failed to start'
  }
  if (isRunning) {
    return 'Running'
  }

  return StatusTextMap[status]
}

export const useStatusInfo = (
  status: BuildStatusType,
  statusChangeComment?: CommentInfo | null,
  canceledInfo?: CommentInfo | null,
  waitReason?: string,
  failedToStart?: boolean,
  isRunning?: boolean,
  type = EntityType.BUILD,
) => {
  const statusText = useStatusText(
    status,
    statusChangeComment,
    canceledInfo,
    isRunning,
    failedToStart,
  )

  const userDisplayName = useUserDisplayName(canceledInfo?.user ?? statusChangeComment?.user, true)
  const userText = userDisplayName != null ? ` by ${userDisplayName}` : ''
  const entity = EntityTextMap[type]
  let tooltipText = statusText

  if (status === BuildStatusType.QUEUED && waitReason) {
    tooltipText = waitReason
  }
  if (status === BuildStatusType.FAILURE) {
    tooltipText = `${entity} failed`
  }
  if (failedToStart) {
    tooltipText = `${entity} failed to start`
  }
  if (status === BuildStatusType.SUCCESS) {
    tooltipText = `${entity} finished successfully`
  }
  if (isRunning) {
    tooltipText = `${entity} is running`
  }
  if (statusChangeComment) {
    const commentText = statusChangeComment?.text ? statusChangeComment?.text : ''
    const separator = `${userText && commentText ? ': ' : ''}`
    tooltipText = `${userText}${separator}${commentText}`
  }
  if (canceledInfo) {
    const commentText = canceledInfo?.text ? canceledInfo?.text : ''
    const separator = `${userText && commentText ? ': ' : ''}`
    tooltipText = `${userText}${separator}${commentText}`
  }

  return {
    statusText,
    tooltipText,
  }
}

export const useStatusIcon = (
  status: BuildStatusType,
  isRunning?: boolean,
  failedToStart?: boolean,
) => {
  if (isRunning) {
    return 'running'
  }
  if (failedToStart) {
    return 'failedToStart'
  }

  return StatusIconMap[status]
}
