import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo, useCallback, useMemo, useState} from 'react'

import {formatDuration} from '../../../../../../utils/dateTimeUtils'
import Tooltip from '../../../../../pages/PipelinesPages/components/Tooltip/Tooltip'
import {HUNDRED_PERCENT} from '../../TimeBadge.constants'

import styles from './OptimizationsChart.module.css'

import type {RunDuration} from 'src/components/pages/PipelinesPages/services/pipelinesApi.types'

const VISIBLE_RUNS_COUNT = 9

type Props = {
  runs: RunDuration[]
}
function OptimizationsChart({runs: allRuns}: Props) {
  const runs = [...allRuns].sort((a, b) => a.number - b.number)
  const durations = useMemo(() => runs.map(run => run.duration + (run?.optimized ?? 0)), [runs])
  const maxDuration = useMemo(() => Math.max(...durations), [durations])

  const [start, setStart] = useState(
    runs.length - VISIBLE_RUNS_COUNT < 0 ? 0 : runs.length - VISIBLE_RUNS_COUNT,
  )
  const visibleRuns = useMemo(() => runs.slice(start, start + VISIBLE_RUNS_COUNT), [runs, start])

  const onLeftArrowClick = useCallback(() => {
    setStart(prevState => {
      const value = prevState - VISIBLE_RUNS_COUNT
      return value < 0 ? 0 : value
    })
  }, [])

  const onRightArrowClick = useCallback(() => {
    setStart(prevState => {
      const value = prevState + VISIBLE_RUNS_COUNT
      return value + VISIBLE_RUNS_COUNT > runs.length ? runs.length - VISIBLE_RUNS_COUNT : value
    })
  }, [runs.length])

  const renderTooltip = useCallback(
    (number: number, duration: number, optimized?: number) => (
      <>
        <div className={styles.heading}>{`Run #${number}`}</div>
        {optimized ? (
          <div className={styles.row}>
            <span className={classNames(styles.bullet, styles.optimized)} />
            <span>{'Time saved'}</span>
            <span className={styles.value}>{formatDuration(optimized)}</span>
          </div>
        ) : null}
        <div className={styles.row}>
          <span className={styles.bullet} />
          <span>{'Run duration'}</span>
          <span className={styles.value}>{formatDuration(duration)}</span>
        </div>
      </>
    ),
    [],
  )

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <div className={styles.heading}>{'Original and optimized run duration'}</div>
        <div className={styles.arrows}>
          <IconButton
            className={classNames(styles.arrow, {[styles.disabled]: start === 0})}
            icon={'chevron-left'}
            title={'Previous'}
            iconClassName={styles.icon}
            disabled={start === 0}
            onClick={onLeftArrowClick}
          />
          <IconButton
            className={classNames(styles.arrow, {
              [styles.disabled]: start + VISIBLE_RUNS_COUNT >= runs.length,
            })}
            icon={'chevron-right'}
            title={'Next'}
            iconClassName={styles.icon}
            disabled={start + VISIBLE_RUNS_COUNT >= runs.length}
            onClick={onRightArrowClick}
          />
        </div>
      </div>

      <div className={styles.chart}>
        <div className={styles.axes}>
          <div className={styles.numberAxis}>
            <div className={styles.lines}>
              <div className={styles.dashedLine} />
              <div className={styles.dashedLine} />
              <div className={styles.line} />
            </div>

            {visibleRuns.map(({number, duration, optimized = 0, canceled}) => {
              const height = (HUNDRED_PERCENT * (optimized + duration)) / maxDuration
              const optimizedHeight = optimized
                ? (HUNDRED_PERCENT * optimized) / (optimized + duration)
                : 0
              return (
                <div className={styles.chartBarContainer} key={number}>
                  {canceled ? (
                    <div className={styles.canceledChartBar} style={{height: `${height}%`}} />
                  ) : (
                    <div className={styles.tooltipContainer}>
                      <Tooltip
                        style={{height: `${height}%`}}
                        className={styles.tooltip}
                        title={renderTooltip(number, duration, optimized)}
                        popupProps={{
                          directions: [Directions.TOP_CENTER],
                          offset: 8,
                        }}
                      >
                        <div className={styles.chartBar}>
                          {optimizedHeight ? (
                            <div
                              style={{height: `${optimizedHeight}%`}}
                              className={styles.chartBarOptmized}
                            />
                          ) : null}
                        </div>
                      </Tooltip>
                    </div>
                  )}
                  <div className={styles.value}>{number}</div>
                </div>
              )
            })}
          </div>

          <div className={classNames(styles.timeAxis, styles.value)}>
            <div>{formatDuration(maxDuration, {hideZero: true}).split(' ')[0]}</div>
            <div>{formatDuration(maxDuration / 2, {hideZero: true}).split(' ')[0]}</div>
            <div>{'0m'}</div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default memo(OptimizationsChart)
