import Link from '@jetbrains/ring-ui-built/components/link/link'
import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import {memo, useId} from 'react'

import Tooltip from '../../../../../pages/PipelinesPages/components/Tooltip/Tooltip'
import type {
  PossibleOptimization,
  Optimizations,
} from '../../../../../pages/PipelinesPages/services/pipelinesApi.types'
import Icon from '../../../../Icon/Icon'
import SwitcherLabel from '../../../../SwitcherLabel/SwitcherLabel'
import {OPTIMIZATION_OPTIONS} from '../OptimizationsPopup.consts'

import {
  COMING_SOON_OPTIMIZATIONS,
  DOCUMENTATION_LINK,
  OPTIMIZATION_ACNHORS,
} from './PossibleOptimizations.consts'

import styles from './PossibleOptimizations.module.css'

type Props = {
  optimizations: PossibleOptimization[]
}
function PossibleOptimizations({optimizations}: Props) {
  const id = useId()
  return (
    <div className={styles.container}>
      <div className={styles.optimizations}>
        {optimizations.map((value, index) => {
          const optimization = OPTIMIZATION_OPTIONS[value.name as Optimizations]
          return (
            // eslint-disable-next-line react/no-array-index-key
            <div key={index} className={styles.optimization}>
              <div className={styles.nameTag}>
                {COMING_SOON_OPTIMIZATIONS.includes(value) ? (
                  <Tag className={styles.comingSoonTag} readOnly>
                    {'Coming soon'}
                  </Tag>
                ) : (
                  <SwitcherLabel on={false} />
                )}
                <span>{optimization.name}</span>
              </div>

              {Object.keys(OPTIMIZATION_ACNHORS).includes(value.name) && (
                <Tooltip title="Documentation" id={id}>
                  <Link
                    aria-labelledby={id}
                    className={styles.link}
                    href={`${DOCUMENTATION_LINK}${[OPTIMIZATION_ACNHORS[value.name as Optimizations]]}`}
                    target="_blank"
                    rel="noreferrer"
                  >
                    <Icon name={'info'} />
                  </Link>
                </Tooltip>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

export default memo(PossibleOptimizations)
