import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import classNames from 'classnames'
import {memo} from 'react'

import styles from './SwitcherLabel.module.css'

type Props = {
  on?: boolean
  className?: string
}

function SwitcherLabel({on, className}: Props) {
  return (
    <div className={styles.wrapper}>
      <Tag readOnly className={classNames(styles.label, {[styles.on]: on}, className)}>
        {on ? 'On' : 'Off'}
      </Tag>
    </div>
  )
}

export default memo(SwitcherLabel)
